const BCH_SPACING: u64 = 600;
const BCH_HALF_LIFE: u64 = 172_800;

fn parse_hex_u256(s: &str) -> U256 {
    let padded = format!("{s:0>64}");
    U256::from_be_bytes(hex::decode(padded).unwrap().try_into().unwrap())
}

fn parse_bits(s: &str) -> u32 {
    u32::from_str_radix(s.trim().trim_start_matches("0x"), 16).unwrap()
}

struct Run {
    anchor_height: u64,
    anchor_parent_time: i128,
    anchor_bits: u32,
    /// (parent height, parent timestamp, expected child bits)
    rows: Vec<(u64, i128, u32)>,
}

fn parse_run(text: &str) -> Run {
    let (mut anchor_height, mut anchor_parent_time, mut anchor_bits, mut iterations) =
        (None, None, None, None);
    let mut rows = Vec::new();
    for line in text.lines() {
        if let Some(meta) = line.strip_prefix("##") {
            let Some((key, value)) = meta.split_once(':') else {
                continue;
            };
            let value = value.trim();
            match key.trim() {
                "anchor height" => anchor_height = Some(value.parse().unwrap()),
                "anchor parent time" => anchor_parent_time = Some(value.parse().unwrap()),
                "anchor nBits" => anchor_bits = Some(parse_bits(value)),
                "iterations" => iterations = Some(value.parse::<usize>().unwrap()),
                _ => {}
            }
        } else if !line.starts_with('#') && !line.trim().is_empty() {
            let cols: Vec<&str> = line.split_whitespace().collect();
            assert_eq!(cols.len(), 4, "{line}");
            rows.push((
                cols[1].parse().unwrap(),
                cols[2].parse().unwrap(),
                parse_bits(cols[3]),
            ));
        }
    }
    assert_eq!(Some(rows.len()), iterations);
    Run {
        anchor_height: anchor_height.unwrap(),
        anchor_parent_time: anchor_parent_time.unwrap(),
        anchor_bits: anchor_bits.unwrap(),
        rows,
    }
}

/// All 14000 official vectors agree one by one. The PoW limit is taken as BCHN's 2^224 − 1 and as the target of
/// 0x1d00ffff (as written in the spec's Python version); both encode to the same bits.
#[test]
fn official_aserti3_2d_vectors() {
    let bch_limit = U256::ONE.shl(224).checked_sub(U256::ONE).unwrap();
    let bits_limit = pow_limit_target(0x1d00_ffff).unwrap();
    let mut total = 0;
    for (name, text, digest) in OFFICIAL {
        assert_eq!(
            hex::encode(sha256(text.as_bytes())),
            digest,
            "{name} has been modified"
        );
        let run = parse_run(text);
        let anchor = target_from_bits(run.anchor_bits, 0x1d00_ffff).unwrap();
        for &(height, time, expected) in &run.rows {
            let time_diff = time - run.anchor_parent_time;
            let height_diff = height - run.anchor_height;
            for limit in [bch_limit, bits_limit] {
                let target = asert_target(
                    &anchor,
                    &limit,
                    BCH_SPACING,
                    BCH_HALF_LIFE,
                    time_diff,
                    height_diff,
                )
                .unwrap();
                assert_eq!(
                    bits_from_target(&target),
                    expected,
                    "{name}: height {height} time {time} limit {limit}"
                );
            }
            total += 1;
        }
    }
    assert_eq!(total, 14_000);
}

/// The vectors generated by `asert_ref.py`: the targets are bit-for-bit identical (not just the bits).
#[test]
fn reference_vectors() {
    let text = include_str!("data/asert_ref_vectors.txt");
    let mut params: Option<(String, u64, u64, U256)> = None;
    let mut anchor: Option<U256> = None;
    let mut genesis: Option<(Asert, PowConsensus, u64)> = None;
    let (mut raw_cases, mut genesis_cases) = (0, 0);
    for line in text
        .lines()
        .filter(|l| !l.starts_with('#') && !l.trim().is_empty())
    {
        let cols: Vec<&str> = line.split_whitespace().collect();
        match cols[0] {
            "P" => {
                params = Some((
                    cols[1].to_string(),
                    cols[2].parse().unwrap(),
                    cols[3].parse().unwrap(),
                    parse_hex_u256(cols[4]),
                ));
                genesis = None;
            }
            "A" => anchor = Some(parse_hex_u256(cols[1])),
            "G" => {
                let pow_limit_bits = parse_bits(cols[2]);
                let p = Params {
                    pow_limit_bits,
                    target_block_time_secs: cols[3].parse().unwrap(),
                    asert_half_life_secs: cols[4].parse().unwrap(),
                    ..DEVNET
                };
                let timestamp = cols[1].parse().unwrap();
                let anchor = BtcAnchor {
                    height: 1,
                    hash: [3; 32],
                };
                let g = genesis_header(&p, timestamp, anchor, [4; 32]).unwrap();
                genesis = Some((
                    Asert::from_genesis(&p, &g).unwrap(),
                    PowConsensus::new(&p, &g).unwrap(),
                    timestamp,
                ));
                params = None;
            }
            _ => {
                if let Some((asert, consensus, genesis_time)) = &genesis {
                    let (height, timestamp, expected) = (
                        cols[0].parse().unwrap(),
                        cols[1].parse().unwrap(),
                        parse_bits(cols[2]),
                    );
                    assert_eq!(
                        asert.next_bits(height, timestamp),
                        Ok(expected),
                        "genesis {genesis_time}: {line}"
                    );
                    let parent = BlockHeader {
                        height,
                        timestamp,
                        ..parent_template()
                    };
                    // a non-empty block on a pure chain: the DAA score equals the height, weight 1 (D-084)
                    if let Some(daa_score) = height.checked_add(1) {
                        assert_eq!(
                            consensus.next_bits(&parent, daa_score, 1),
                            Ok(expected),
                            "{line}"
                        );
                    }
                    genesis_cases += 1;
                } else {
                    let (name, spacing, half_life, limit) = params.as_ref().unwrap();
                    let anchor = anchor.unwrap();
                    let time_diff: i128 = cols[0].parse().unwrap();
                    let height_diff: u64 = cols[1].parse().unwrap();
                    let expected = parse_hex_u256(cols[2]);
                    assert_eq!(
                        asert_target(&anchor, limit, *spacing, *half_life, time_diff, height_diff),
                        Ok(expected),
                        "{name}: anchor {anchor} time_diff {time_diff} height_diff {height_diff}"
                    );
                    raw_cases += 1;
                }
            }
        }
    }
    let footer = text.lines().last().unwrap();
    assert_eq!(footer, format!("# {} cases", raw_cases + genesis_cases));
    assert!(
        raw_cases > 2500 && genesis_cases > 100,
        "{raw_cases} / {genesis_cases}"
    );
}

fn parent_template() -> BlockHeader {
    BlockHeader {
        version: 1,
        height: 0,
        parents: vec![],
        btc_anchor: BtcAnchor {
            height: 0,
            hash: [0; 32],
        },
        entries_root: [0; 32],
        state_root: [0; 32],
        producer: [0; 32],
        timestamp: 0,
        bits: 0,
        nonce: 0,
    }
}

#[test]
fn asert_target_rejects_unusable_parameters() {
    let limit = pow_limit_target(DEVNET.pow_limit_bits).unwrap();
    assert!(matches!(
        asert_target(&limit, &limit, 5, 0, 0, 0),
        Err(ConsensusError::InvalidParams(_))
    ));
    assert!(matches!(
        asert_target(&U256::ZERO, &limit, 5, 600, 0, 0),
        Err(ConsensusError::InvalidParams(_))
    ));
    let above = limit.checked_add(U256::ONE).unwrap();
    assert!(matches!(
        asert_target(&above, &limit, 5, 600, 0, 0),
        Err(ConsensusError::InvalidParams(_))
    ));
    // an anchor equal to the limit and to 1 are both usable; extreme inputs do not overflow
    for anchor in [U256::ONE, limit] {
        for (time_diff, height_diff) in [
            (i128::MIN, u64::MAX),
            (i128::MAX, 0),
            (i128::MAX, u64::MAX),
            (i128::MIN, 0),
        ] {
            let t = asert_target(&anchor, &limit, u64::MAX, 1, time_diff, height_diff).unwrap();
            assert!(t == U256::ONE || t == limit);
        }
    }
}
